import{_ as s,o as r,c as n,l as t,t as a,N as i}from"./chunks/framework.Gjrf2Eoj.js";const m=JSON.parse('{"title":"user-keyring | x-cmd man (man7) | per-user keyring","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | user-keyring - per-user keyring","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"user-keyring | x-cmd man (man7) | per-user keyring"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | user-keyring - per-user keyring"}]]},"headers":[],"params":{"isMan":true,"man":"user-keyring","category":"man7","desc":"per-user keyring"},"relativePath":"man7/user-keyring.md","filePath":"man7/user-keyring.md"}'),o={name:"man7/user-keyring.md"},g={class:"visually-hidden"},h=i('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>user-keyring - per-user keyring</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The user keyring is a keyring used to anchor keys on behalf of a user. Each UID the kernel deals with has its own user keyring that is shared by all processes with that UID. The user keyring has a name (description) of the form <em>_uid.&lt;UID&gt;</em> where <em>&lt;UID&gt;</em> is the user ID of the corresponding user.</p><p>The user keyring is associated with the record that the kernel maintains for the UID. It comes into existence upon the first attempt to access either the user keyring, the <strong>user-session-keyring</strong>(7), or the <strong>session-keyring</strong>(7). The keyring remains pinned in existence so long as there are processes running with that real UID or files opened by those processes remain open. (The keyring can also be pinned indefinitely by linking it into another keyring.)</p><p>Typically, the user keyring is created by <strong>pam_keyinit</strong>(8) when a user logs in.</p><p>The user keyring is not searched by default by <strong>request_key</strong>(2). When <strong>pam_keyinit</strong>(8) creates a session keyring, it adds to it a link to the user keyring so that the user keyring will be searched when the session keyring is.</p><p>A special serial number value, <strong>KEY_SPEC_USER_KEYRING</strong>, is defined that can be used in lieu of the actual serial number of the calling process&#39;s user keyring.</p><p>From the <strong>keyctl</strong>(1) utility, &#39;<strong>@u</strong>&#39; can be used instead of a numeric key ID in much the same way.</p><p>User keyrings are independent of <strong>clone</strong>(2), <strong>fork</strong>(2), <strong>vfork</strong>(2), <strong>execve</strong>(2), and <strong>_exit</strong>(2) excepting that the keyring is destroyed when the UID record is destroyed when the last process pinning it exits.</p><p>If it is necessary for a key associated with a user to exist beyond the UID record being garbage collected---for example, for use by a <strong>cron</strong>(8) script---then the <strong>persistent-keyring</strong>(7) should be used instead.</p><p>If a user keyring does not exist when it is accessed, it will be created.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>keyctl</strong>(1), <strong>keyctl</strong>(3), <strong>keyrings</strong>(7), <strong>persistent-keyring</strong>(7), <strong>process-keyring</strong>(7), <strong>session-keyring</strong>(7), <strong>thread-keyring</strong>(7), <strong>user-session-keyring</strong>(7), <strong>pam_keyinit</strong>(8)</p>',14);function c(e,d,l,p,y,u){return r(),n("div",null,[t("h1",g,a(e.$params.man),1),h])}const _=s(o,[["render",c]]);export{m as __pageData,_ as default};
